/* @autogenerated */
import { APP_INITIALIZER, computed, inject, Injectable, InjectionToken, Signal, signal } from '@angular/core';
import { environment } from 'app/bootstrap/environment/environment';
import { BehaviorSubject, filter, map, Observable } from 'rxjs';
import { AppConfig, ConfigPath, ConfigPathValue, emptyConfig, readPath } from './app-config.model';

export type { AppConfig, ConfigPath, ConfigPathValue } from './app-config.model';

export const STATIC_CONF: InjectionToken<string> = new InjectionToken<string>('STATIC_CONF');

export function provideConfiguration() {
  return [
    {
      provide: APP_INITIALIZER,
      useFactory: (appConfig: _$$_AppConfigService) => {
        return () => appConfig.$$_loadConfig();
      },
      deps: [_$$_AppConfigService],
      multi: true,
    },
    {
      provide: STATIC_CONF,
      deps: [_$$_AppConfigService],
      useFactory: (app: _$$_AppConfigService) => {
        return app.staticValue();
      },
    },
  ];
}

@Injectable({ providedIn: 'root' })
class _$$_AppConfigService {
  /** Configuración cruda para la fachada `AppConfigService`: `null` hasta que se carga. */
  private values = new BehaviorSubject<any>(null);
  private readonly current = signal<AppConfig>(emptyConfig(environment.name));
  private shell = false;
  private loaded = false;
  private env: any;

  public constructor() {
    this.env = environment;
  }

  public staticValue() {
    if (!this.shell) {
      throw new Error('Static configuration is only available on the shell');
    }
    return this.values.value;
  }

  // Método para cargar la configuración
  public async $$_loadConfig(): Promise<void> {
    this.shell = true;
    const response = await fetch('./config/' + this.env.name + '-config.json');
    this.publish(await response.json());
  }

  public registerRemote(name: string, url: string, file: string) {
    if (!(window as any)._remove_mfa_config_url) {
      (window as any)._remove_mfa_config_url = {};
    }
    (window as any)._remove_mfa_config_url[name] = [url, file];
  }

  /** Configuración tipada; con las secciones vacías hasta que se carga. */
  public config(): Signal<AppConfig> {
    this.ensureLoaded();
    return this.current.asReadonly();
  }

  /** Emite la configuración tipada cuando ya se ha cargado, y de nuevo si se recarga. */
  public config$(): Observable<AppConfig> {
    this.ensureLoaded();
    return this.values.pipe(
      filter((v) => v !== null),
      map(() => this.current()),
    );
  }

  // Función para consultar una clave específica de la configuración
  public value(key: string, def?: string): Observable<any> {
    this.ensureLoaded();
    return this.values.pipe(
      map((node) => {
        const path = key.split('.');
        path.forEach((p) => {
          node = node ? node[p] : null;
        });
        return node ?? def;
      }),
    );
  }

  /** En un microfront no hay APP_INITIALIZER: la configuración se pide al primer uso. */
  private ensureLoaded() {
    if (!this.shell && !this.loaded) {
      this.loaded = true;
      this.mfeLoad();
    }
  }

  private mfeLoad() {
    const target = (window as any)._remove_mfa_config_url?.[this.env.name];
    // Sin remoto registrado (p. ej. en tests) no hay de dónde leer: la configuración queda vacía
    if (!target) {
      return;
    }
    (async () => {
      const response = await fetch(target[0] + target[1]);
      this.publish(await response.json());
    })();
  }

  private publish(config: any) {
    const merged = this.deepMerge(this.deepMerge(emptyConfig(this.env.name), this.env), config ?? {});
    this.current.set(merged);
    this.values.next(merged);
  }

  private deepMerge(target: any, source: any): any {
    if (typeof target !== 'object' || typeof source !== 'object') {
      return target;
    }

    for (const key in source) {
      if (source.hasOwnProperty(key)) {
        if (typeof source[key] === 'object' && source[key] !== null && !Array.isArray(source[key])) {
          // Si es un objeto, hacemos merge recursivo
          target[key] = this.deepMerge(target[key] || {}, source[key]);
        } else {
          // Si es un valor primitivo o array, sobrescribir
          target[key] = source[key];
        }
      }
    }

    return target;
  }
}

/** Configuración en runtime tipada. Antes de cargarse, cada sección está vacía. */
export const APP_CONFIG = new InjectionToken<Signal<AppConfig>>('APP_CONFIG', {
  providedIn: 'root',
  factory: () => inject(_$$_AppConfigService).config(),
});

/** Acceso tipado a la configuración: `value('identity.main.issuer')` con autocompletado de la ruta. */
@Injectable({ providedIn: 'root' })
export class RuntimeConfigService {
  private readonly base = inject(_$$_AppConfigService);
  readonly config: Signal<AppConfig> = inject(APP_CONFIG);
  /** Emite la configuración cuando ya se ha cargado (no emite el estado vacío). */
  readonly config$: Observable<AppConfig> = this.base.config$();

  /** El valor de `path`, que se actualiza si la configuración se recarga. */
  value<P extends ConfigPath>(path: P): Signal<ConfigPathValue<P> | undefined> {
    return computed(() => readPath(this.config(), path));
  }

  /** El valor de `path` cuando la configuración ya se ha cargado (no emite el estado vacío). */
  value$<P extends ConfigPath>(path: P): Observable<ConfigPathValue<P> | undefined> {
    return this.config$.pipe(map((config) => readPath(config, path)));
  }
}

/** Atajo de `RuntimeConfigService.value()`. Requiere contexto de inyección. */
export function configValue<P extends ConfigPath>(path: P): Signal<ConfigPathValue<P> | undefined> {
  return inject(RuntimeConfigService).value(path);
}

/**
 * @deprecated Sin tipos: una errata devuelve `undefined` sin avisar. Usa `RuntimeConfigService`,
 * `configValue()` o `APP_CONFIG`.
 */
@Injectable({ providedIn: 'root' })
export class AppConfigService {
  [key: string]: Observable<any>;
  public constructor(base: _$$_AppConfigService) {
    return new Proxy(
      {},
      {
        get: (_, prop) => {
          return base.value(prop as string);
        },
      },
    );
  }
}

@Injectable({ providedIn: 'root' })
export class MicroFrontConfigService {
  public constructor(private readonly base: _$$_AppConfigService) {}
  public registerRemote(name: string, url: string, file: string) {
    this.base.registerRemote(name, url, file);
  }
}
